/**
 * A paragraph of body text (`design/components/text.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/text.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { Component, ViewEncapsulation, input } from '@angular/core'

import { MEMBER_PROVIDERS, SlotOutlet, SlotTemplate, derived, useMember } from '@polymorph/angular'
import styles from '@polymorph/recipes/structure/text.module.css'

export type TextSize = NonNullable<TextProps['size']>

export type TextTone = NonNullable<TextProps['tone']>

/** A paragraph of body text: the inputs it takes, by the React member's prop names. */
export interface TextProps {
  /**
   * The most lines the paragraph draws; the last ends with an ellipsis. Only the drawing is cut,
   * so the whole text must be reachable another way (the page it opens, a detail view). A value
   * that is not a whole number reads as the whole number below it, and below 1 nothing is cut.
   */
  lines?: number
  size?: 'sm' | 'md'
  /**
   * Never below secondary; muted text is a caption, and captions belong to the components that
   * own them.
   */
  tone?: 'primary' | 'secondary'
}

/** A paragraph of body text. */
@Component({
  selector: 'pm-text',
  encapsulation: ViewEncapsulation.None,
  host: { style: 'display: contents' },
  providers: [...MEMBER_PROVIDERS],
  imports: [SlotOutlet, SlotTemplate],
  // prettier-ignore
  template: `<ng-template pmSlot="default" [pmSlotOf]="$"><ng-content /></ng-template>
<p
[attr.class]="e1()"
[style.--pm-text-clamp]="e2()"
[attr.data-size]="e3()"
[attr.data-tone]="e4()"
[attr.data-lines]="e2()"
data-member="text"
><ng-container [pmSlotOutlet]="'default'" [pmSlotOf]="$" /></p>`,
})
export class Text {
  /**
   * The most lines the paragraph draws; the last ends with an ellipsis. Only the drawing is cut,
   * so the whole text must be reachable another way (the page it opens, a detail view). A value
   * that is not a whole number reads as the whole number below it, and below 1 nothing is cut.
   */
  readonly lines = input<TextProps['lines']>(undefined)
  readonly size = input<Exclude<TextProps['size'], undefined>, TextProps['size']>('md', {
    transform: (value: TextProps['size']) => (value === undefined ? 'md' : value),
  })
  /**
   * Never below secondary; muted text is a caption, and captions belong to the components that
   * own them.
   */
  readonly tone = input<Exclude<TextProps['tone'], undefined>, TextProps['tone']>('primary', {
    transform: (value: TextProps['tone']) => (value === undefined ? 'primary' : value),
  })
  protected readonly $ = useMember({
    events: [],
    props: { lines: () => this.lines(), size: () => this.size(), tone: () => this.tone() },
  })
  protected readonly $p = this.$.props
  protected readonly kept = derived(() =>
    this.$p.lines === undefined ? 0 : Math.floor(this.$p.lines),
  )
  protected readonly clamped = derived(() => this.kept.value >= 1)

  protected e1() {
    return styles.text
  }

  protected e2() {
    return this.clamped.value ? this.kept.value : undefined
  }

  protected e3() {
    return this.$p.size
  }

  protected e4() {
    return this.$p.tone
  }
}
